package local.skyfamily;
import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.os.*;import android.view.View;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
final class SavedPhotoPreview {
 final CalendarPhotosActivity host;final Handler main=new Handler();final ArrayList<Target> targets=new ArrayList<>();String key="",message="Loading photos";Bitmap bitmap;long fetched=0;volatile int serial=0;boolean loading=false;volatile boolean closed=false;Source pending;int pendingSerial,pendingWidth,pendingHeight,loadedWidth=0,loadedHeight=0;
 static class Target{ImageView image;TextView label;int revision;View.OnLayoutChangeListener listener;Target(ImageView i,TextView l,int r){image=i;label=l;revision=r;}}
 static class Source{String key,server,token;boolean local,waiting;File file;ArrayList<String> albums=new ArrayList<>();}
 static class Decoded{Bitmap bitmap;int width,height;Decoded(Bitmap image,int w,int h){bitmap=image;width=w;height=h;}}
 SavedPhotoPreview(CalendarPhotosActivity activity){host=activity;}
 void prune(){for(Iterator<Target> iterator=targets.iterator();iterator.hasNext();){Target target=iterator.next();if(target.revision!=host.revision){target.image.removeOnLayoutChangeListener(target.listener);iterator.remove();}}}
 void bind(ImageView image,TextView label){prune();Target target=new Target(image,label,host.revision);target.listener=(view,l,t,r,b,ol,ot,or,ob)->{if(r-l!=or-ol||b-t!=ob-ot)refresh(false);};targets.add(target);image.addOnLayoutChangeListener(target.listener);refresh(false);render();}
 void clearTargets(){for(Target target:targets)target.image.removeOnLayoutChangeListener(target.listener);targets.clear();}
 Source source(){Source source=new Source();source.server=host.server;source.token=host.token;source.local=host.prefs.getBoolean("gallery.local",false)||host.token.isEmpty()&&host.get("immich.vault").isEmpty();if(source.local){File[] images=new File(host.getFilesDir(),"uploads").listFiles((directory,name)->name.endsWith(".image"));if(images!=null&&images.length>0){Arrays.sort(images,(a,b)->Long.compare(b.lastModified(),a.lastModified()));source.file=images[0];}source.key="local:"+(source.file==null?"none":source.file.getName()+":"+source.file.lastModified());}else if(source.token.isEmpty()){source.waiting=true;source.key="waiting:"+host.get("immich.vault").hashCode();}else{source.albums.addAll(host.selection());Collections.sort(source.albums);source.key=host.signature(source.server,source.token,new LinkedHashSet<String>(source.albums));}return source;}
 int[] measuredSize(){int width=0,height=0;for(Target target:targets){if(target.revision!=host.revision)continue;int w=target.image.getWidth()-target.image.getPaddingLeft()-target.image.getPaddingRight(),h=target.image.getHeight()-target.image.getPaddingTop()-target.image.getPaddingBottom();if(w>0&&h>0){width=Math.max(width,w);height=Math.max(height,h);}}return new int[]{Math.min(4096,width),Math.min(4096,height)};}
 void refresh(boolean force){if(closed)return;prune();Source source=source();if(force||!source.key.equals(key)){serial++;key=source.key;bitmap=null;fetched=0;loadedWidth=loadedHeight=0;loading=false;main.removeCallbacks(load);}if(source.waiting){message=Build.VERSION.SDK_INT<18?"Unlock saved photo session to load albums":"Restoring saved photo session...";render();return;}if(source.local&&source.file==null){message="No uploaded photos yet";render();return;}int[] size=measuredSize();if(size[0]<1||size[1]<1){render();return;}if(bitmap!=null&&!force&&System.currentTimeMillis()-fetched<300000&&loadedWidth>=size[0]&&loadedHeight>=size[1]){render();return;}if(loading){if(pendingWidth>=size[0]&&pendingHeight>=size[1]){render();return;}serial++;loading=false;main.removeCallbacks(load);}loading=true;message=bitmap!=null?"Improving photo quality...":source.local?"Loading uploaded photo...":"Loading saved album selection...";pending=source;pendingSerial=serial;pendingWidth=size[0];pendingHeight=size[1];render();main.removeCallbacks(load);main.postDelayed(load,250);}
 boolean stale(int ticket){return closed||ticket!=serial;}
 int downloadLimit(){return (int)Math.max(2097152L,Math.min(12582912L,Runtime.getRuntime().maxMemory()/8));}
 final Runnable load=this::loadPreview;
 void loadPreview(){final Source selected=pending;final int ticket=pendingSerial,width=pendingWidth,height=pendingHeight;if(selected==null||stale(ticket))return;host.work(()->{try{Bitmap image;String label;if(selected.local){image=decodeFile(selected.file,width,height).bitmap;label="Uploaded photos";}else{JSONObject fallback=null,chosen=null;ArrayList<String> albums=new ArrayList<>(selected.albums);if(albums.isEmpty())albums.add("");for(String album:albums){if(stale(ticket))return;JSONObject query=new JSONObject().put("size",24).put("page",1);if(!album.isEmpty())query.put("albumIds",new JSONArray().put(album));JSONObject response=new JSONObject(new String(host.request(selected.server+"/search/metadata","POST",query.toString(),selected.token,6000000),"UTF-8"));JSONArray items=response.getJSONObject("assets").getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String id=item.optString("id");if(!id.matches("[A-Za-z0-9-]+"))continue;if(item.optString("type").equals("IMAGE")){chosen=item;break;}if(fallback==null&&item.optString("type").equals("VIDEO"))fallback=item;}if(chosen!=null)break;}if(chosen==null)chosen=fallback;if(chosen==null)throw new IOException("No media found in saved selection");if(stale(ticket))return;String endpoint=selected.server+"/assets/"+chosen.getString("id")+"/thumbnail?size=";Decoded preview=decode(host.request(endpoint+"preview","GET",null,selected.token,downloadLimit()),width,height);boolean video=chosen.optString("type").equals("VIDEO");if(!video&&(preview.width<width||preview.height<height)&&!stale(ticket)){try{Decoded larger=decode(host.request(endpoint+"fullsize","GET",null,selected.token,downloadLimit()),width,height);if(larger.bitmap.getWidth()>=preview.bitmap.getWidth()&&larger.bitmap.getHeight()>=preview.bitmap.getHeight())preview=larger;}catch(Exception ignored){}catch(OutOfMemoryError ignored){}}image=preview.bitmap;label=(video?"Video preview / ":"")+(selected.albums.isEmpty()?"Whole Immich library":selected.albums.size()+" saved album(s)");}final Bitmap ready=image;final String caption=label;main.post(()->{if(stale(ticket)||!selected.key.equals(source().key))return;bitmap=ready;loadedWidth=width;loadedHeight=height;fetched=System.currentTimeMillis();loading=false;message=caption;render();});}catch(Exception error){main.post(()->{if(!stale(ticket)){loading=false;message="Photos unavailable / "+error.getMessage();render();}});}catch(OutOfMemoryError error){main.post(()->{if(!stale(ticket)){loading=false;message="Photos unavailable / not enough memory";render();}});}});}
 BitmapFactory.Options options(int width,int height,int targetWidth,int targetHeight)throws IOException{if(width<1||height<1||width>100000||height>100000)throw new IOException("Unsupported photo");BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;options.inScaled=false;options.inDither=false;options.inSampleSize=1;while(options.inSampleSize<=16384&&width/(options.inSampleSize*2)>=targetWidth&&height/(options.inSampleSize*2)>=targetHeight)options.inSampleSize*=2;long bytes=Math.max(2097152L,Math.min(12582912L,Runtime.getRuntime().maxMemory()/24)),pixels=bytes/4;while(((width+(long)options.inSampleSize-1)/options.inSampleSize)*((height+(long)options.inSampleSize-1)/options.inSampleSize)>pixels)options.inSampleSize*=2;return options;}
 Decoded decode(byte[] bytes,int width,int height)throws IOException{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);Bitmap value=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options(bounds.outWidth,bounds.outHeight,width,height));if(value==null)throw new IOException("Unsupported photo");value.setDensity(Bitmap.DENSITY_NONE);return new Decoded(value,bounds.outWidth,bounds.outHeight);}
 Decoded decodeFile(File file,int width,int height)throws IOException{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),bounds);Bitmap value=BitmapFactory.decodeFile(file.getPath(),options(bounds.outWidth,bounds.outHeight,width,height));if(value==null)throw new IOException("Unsupported photo");value.setDensity(Bitmap.DENSITY_NONE);return new Decoded(value,bounds.outWidth,bounds.outHeight);}
 void render(){prune();for(Target target:targets){if(bitmap==null){if(target.image.getDrawable()!=null)target.image.setImageDrawable(null);}else if(!(target.image.getDrawable() instanceof BitmapDrawable)||((BitmapDrawable)target.image.getDrawable()).getBitmap()!=bitmap){target.image.setImageBitmap(bitmap);if(target.image.getDrawable() instanceof BitmapDrawable)((BitmapDrawable)target.image.getDrawable()).setFilterBitmap(true);}target.label.setText(message);}}
 void failure(String text){serial++;loading=false;main.removeCallbacks(load);bitmap=null;loadedWidth=loadedHeight=0;message=text;render();}
 void clear(){failure("Photo connection cleared");key="";fetched=0;}
 void close(){closed=true;serial++;main.removeCallbacksAndMessages(null);clearTargets();bitmap=null;}
}
